def _get(url: str, timeout: float=3) -> tuple[int, bytes]:
    request = urllib.request.Request(url, headers={'Cache-Control': 'no-store'})
    with urllib.request.urlopen(request, timeout=timeout) as response:
        return (response.status, response.read())

def _already_running(url: str, expected_page: str, expected_storage: Path | None) -> str:
    """"same" only when a Web Alarm with the very same page AND the very same storage serves the port."""
    if expected_storage is None:
        return 'other'
    try:
        status, body = _get(url + 'status')
        page_status, page = _get(url)
        storage = json.loads(body).get('storage_root')
    except (OSError, ValueError, AttributeError):
        return 'other'
    same_storage = isinstance(storage, str) and os.path.normcase(str(Path(storage).resolve())) == os.path.normcase(str(expected_storage.resolve()))
    if status == 200 and page_status == 200 and same_storage and (page.decode('utf-8', 'replace') == expected_page):
        return 'same'
    return 'other'

def standard_port() -> int:
    """8765, or this computer's own binding from WEB_ALARM_PORT."""
    raw = os.environ.get('WEB_ALARM_PORT', '').strip()
    if not raw:
        return STANDARD_PORT
    if not raw.isdigit() or not 1024 <= int(raw) <= 65535:
        raise LaunchConfigError(f'WEB_ALARM_PORT={raw!r}: нужен номер порта 1024–65535.')
    return int(raw)

def _profile(name: str, raw: Any) -> Launch:
    if not isinstance(raw, dict):
        raise LaunchConfigError(f'Профиль {name!r}: ожидается объект.')
    kind = raw.get('kind')
    allowed = _WEB_KEYS if kind == 'web_alarm' else _SCRIPT_KEYS if kind == 'python_script' else None
    if allowed is None:
        raise LaunchConfigError(f'Профиль {name!r}: kind должен быть "web_alarm" или "python_script".')
    unknown = sorted(set(raw) - allowed)
    if unknown:
        raise LaunchConfigError(f'Профиль {name!r}: неизвестные поля {unknown}.')
    title = raw.get('title')
    if not isinstance(title, str) or not title.strip() or len(title) > 120:
        raise LaunchConfigError(f'Профиль {name!r}: нужно понятное название title (до 120 символов).')
    if kind == 'python_script':
        script = raw.get('script')
        args = raw.get('args', [])
        if not isinstance(script, str) or not script.endswith('.py') or '\\' in script or script.startswith('/'):
            raise LaunchConfigError(f'Профиль {name!r}: script — путь .py внутри проекта через "/".')
        target = (REPO / script).resolve()
        if REPO not in target.parents or not target.is_file():
            raise LaunchConfigError(f'Профиль {name!r}: скрипт {script!r} не найден внутри проекта.')
        if not isinstance(args, list) or not all((isinstance(item, str) for item in args)):
            raise LaunchConfigError(f'Профиль {name!r}: args — список строк.')
        return Launch(name=name, title=title.strip(), standard=False, kind=kind, storage='script', port=0, script=script, args=tuple(args))
    if raw.get('storage') != 'temp':
        raise LaunchConfigError(f'Профиль {name!r}: тестовый запуск основного приложения использует только storage "temp" — штатное хранилище пользователя ему недоступно.')
    port = raw.get('port')
    if not isinstance(port, int) or isinstance(port, bool) or (not 1024 <= port <= 65535):
        raise LaunchConfigError(f'Профиль {name!r}: port — число 1024–65535.')
    if port == standard_port():
        raise LaunchConfigError(f'Профиль {name!r}: порт {port} занят стандартным запуском; нужен другой.')
    flags = {key: raw.get(key, True) for key in ('folder_picker', 'ultra_chat')}
    if not all((isinstance(value, bool) for value in flags.values())):
        raise LaunchConfigError(f'Профиль {name!r}: folder_picker и ultra_chat — true или false.')
    return Launch(name=name, title=title.strip(), standard=False, kind=kind, storage='temp', port=port, **flags)

def load_launch(config_path: Path=CONFIG_PATH) -> Launch:
    """The launch chosen by the configuration; a missing file means the standard launch."""
    if not config_path.exists():
        return standard_launch()
    try:
        data = json.loads(config_path.read_text(encoding='utf-8'), object_pairs_hook=_strict_object)
    except (OSError, UnicodeDecodeError, ValueError) as exc:
        if isinstance(exc, LaunchConfigError):
            raise
        raise LaunchConfigError('launch_config.json не читается как JSON. ' + RETURN_HINT) from None
    if not isinstance(data, dict) or data.get('schema_version') != 1 or set(data) - _CONFIG_KEYS:
        raise LaunchConfigError('launch_config.json: ожидается объект schema_version 1 с полями active и test_profiles.')
    active = data.get('active', STANDARD)
    profiles = data.get('test_profiles', {})
    if not isinstance(profiles, dict):
        raise LaunchConfigError('launch_config.json: test_profiles — объект.')
    if STANDARD in profiles:
        raise LaunchConfigError('launch_config.json: стандартный запуск встроен и не переопределяется профилем.')
    if active == STANDARD:
        return standard_launch()
    if not isinstance(active, str) or active not in profiles:
        raise LaunchConfigError(f'launch_config.json: профиль {active!r} не найден. ' + RETURN_HINT)
    return _profile(active, profiles[active])

def main(argv: list[str] | None=None, out: TextIO | None=None) -> int:
    parser = argparse.ArgumentParser(prog='Start_WebAlarm.bat', description='Web Alarm Ultra launcher')
    selection = parser.add_mutually_exclusive_group()
    selection.add_argument('--config', type=Path, default=CONFIG_PATH, help='other launch_config.json (tests)')
    selection.add_argument('--standard', action='store_true', help='built-in standard launch, ignoring active config')
    parser.add_argument('--require-test', action='store_true', help='refuse any fallback to the standard launch')
    parser.add_argument('--self-test', type=Path, help='start, check over HTTP, stop and write a JSON result')
    parser.add_argument('--no-browser', action='store_true')
    args = parser.parse_args(argv)
    out = out or sys.stdout
    colors = enable_colors(out)
    try:
        launch = standard_launch() if args.standard else load_launch(args.config)
        if args.require_test and launch.standard:
            raise LaunchConfigError('Тестовый запуск требует явно выбранного TEST-профиля. Файл отсутствует или выбран standard; запуск штатных данных запрещён.')
    except LaunchConfigError as exc:
        out.write('\n' + paint('ЗАПУСК ОСТАНОВЛЕН: конфигурация запуска не принята', 41, colors) + '\n' + str(exc) + '\n')
        return 2
    if launch.kind == 'python_script':
        if args.self_test is not None:
            out.write('Самопроверка для тестового скрипта не поддерживается.\n')
            return 2
        return run_script(launch, out=out, colors=colors)
    return run_web_alarm(launch, out=out, colors=colors, open_browser=not args.no_browser, self_test=args.self_test)

async def execute_request(request: PreparedRequest, *, transport: ChatTransport, cancelled: Callable[[], bool] | None=None) -> ChatResult:
    """One injected invocation, no retries. Caller owns durable accounting/Turn.

    The predicate is checked before and after the call, not a background watcher.
    Task cancellation and deadline after invocation are conservative UNKNOWN.
    Adapters must cooperate with cancellation. A fired deadline remains expired
    even when the adapter suppresses cancellation and returns a response.
    """
    if type(request) is not PreparedRequest:
        raise PreparationError('invalid_prepared_request')
    try:
        rebuilt = prepare_request(model_id=request.model.model_id, context=[{'role': m.role, 'content': m.content} for m in request.messages[:-1]], user_text=request.messages[-1].content, context_ref=request.context_ref, limits=request.limits)
        if rebuilt != request:
            raise PreparationError('stale_or_invalid_request')
        if not callable(getattr(transport, 'send', None)):
            raise PreparationError('transport_required')
        if _cancelled(cancelled):
            return _result(request, Outcome.CANCELLED_BEFORE_START, Execution.NOT_STARTED, code='cancelled_before_start')
    except Exception:
        return _result(request, Outcome.REJECTED, Execution.NOT_STARTED, code='preflight_rejected')
    loop = asyncio.get_running_loop()
    timeout_seconds = request.limits.timeout_seconds
    deadline = loop.time() + timeout_seconds
    timer = asyncio.timeout_at(deadline)

    async def send():
        async with timer:
            return await transport.send(request.payload, timeout_seconds=timeout_seconds)
    owner = asyncio.current_task()
    cancel_count = owner.cancelling()
    try:
        response = await asyncio.create_task(send())
    except (TimeoutError, asyncio.CancelledError):
        return _result(request, Outcome.UNKNOWN_AFTER_START, Execution.MAY_HAVE_EXECUTED, code='cancelled_or_timed_out_after_start')
    except Exception:
        return _result(request, Outcome.TRANSPORT_ERROR, Execution.MAY_HAVE_EXECUTED, code='transport_failed_after_start')
    result = parse_response(request, response)
    try:
        interrupted = _cancelled(cancelled)
    except Exception:
        interrupted = True
    if timer.expired() or loop.time() >= deadline or owner.cancelling() > cancel_count or interrupted:
        return _result(request, Outcome.UNKNOWN_AFTER_START, Execution.RESPONSE_RECEIVED, code='late_or_cancelled_response', usage=result.usage, metadata=result.metadata)
    return result

class LiveCheckNotAuthorized:
    """The shipped checker: a real request to a paid API needs a separate user decision."""
    authorized = False
    reason = 'Настоящий запрос к API в этой версии не разрешён: нужен отдельный USER GO (ключи, тарифицируемые запросы).'

    def check(self, request: CheckRequest) -> CheckResult:
        raise CheckRefusedError(self.reason)

def run_check(self, model_id: Any) -> dict[str, Any]:
    """One fixed short test message through the configured checker; nothing is sent while the live
        check is not authorised, and a simulated answer never confirms the model."""
    ctx = self._context()
    spec = self._spec(ctx['registry'], model_id)
    card = self._card(ctx, spec)
    if not spec.enabled:
        raise CheckRefusedError(f'model {spec.model_id!r} is disabled in the shared registry')
    if card['api']['reason'] == 'ADAPTER_MISSING':
        raise CheckRefusedError(f'provider {spec.provider!r} has no adapter')
    if not self.checker.authorized:
        return {'outcome': 'LIVE_CHECK_NOT_AUTHORIZED', 'message': self.checker.reason, 'network_calls': 0, 'test_message': TEST_MESSAGE, 'card': card}
    provider = ctx['settings']['providers'][spec.provider]
    profile = self._profile_for(ctx['settings'], spec)
    version = card['settings_version']
    request = CheckRequest(card['connection_id'], spec.model_id, spec.provider, spec.provider_model_id, provider.api_url, profile['timeout_seconds'], TEST_MESSAGE)
    try:
        result = self.checker.check(request)
    except CheckRefusedError:
        raise
    except Exception as exc:
        result = CheckResult(ok=False, live=True, error_code='checker_error', error_message=type(exc).__name__)
    limit = profile['diagnostic_limit_chars']
    if not result.live:
        outcome = 'SIMULATED'
        text = safe_text(result.reply or result.error_message or '', limit)
    elif result.ok:
        outcome = 'CONFIRMED'
        self.record_success(card['connection_id'], version, source='diagnostic', reply=result.reply or '', limit=limit)
        text = safe_text(result.reply or '', limit)
    else:
        outcome = 'FAILED'
        self.record_failure(card['connection_id'], version, code=result.error_code or 'check_failed', message=result.error_message or '', limit=limit)
        text = safe_text(f"{result.error_code or 'check_failed'}: {result.error_message or ''}", limit)
    return {'outcome': outcome, 'text': text, 'test_message': TEST_MESSAGE, 'card': self.card(spec.model_id)}

def _settings_version(self, spec: Any, provider: Provider | None, profile: dict[str, Any], facts: dict[str, Any]) -> str:
    """Changes when the key, the API profile, an endpoint or the called model changes; card text,
        parameter count, timeouts and the freshness period are deliberately outside."""
    material = {'provider': spec.provider, 'adapter': provider.adapter if provider else None, 'profile_id': profile['profile_id'], 'credential_env': provider.credential_env if provider else None, 'credential_present': facts['credential']['present'], 'credential_revision': profile['credential_revision'], 'scope': facts['scope']['value'], 'oauth_url': provider.oauth_url if provider else None, 'api_url': provider.api_url if provider else None, 'provider_model_id': spec.provider_model_id}
    canonical = json.dumps(material, ensure_ascii=True, sort_keys=True, separators=(',', ':'))
    return hashlib.sha256(canonical.encode('ascii')).hexdigest()[:16]

def catalog(self) -> dict[str, Any]:
    """Everything the EVM cards show; reads only, creates nothing, sends nothing."""
    ctx = self._context()
    settings, tk = (ctx['settings'], ctx['tk'])
    providers = []
    for provider in settings['providers'].values():
        facts = self._connection_facts(provider)
        providers.append({'provider_id': provider.provider_id, 'display_name': provider.display_name, 'country': provider.country, 'source': provider.source, 'adapter': provider.adapter, 'adapter_state': _adapter_state(provider), 'auth': provider.auth, 'oauth_url': provider.oauth_url, 'api_url': provider.api_url, **facts})
    return {'network_calls': 0, 'settings': {'state': settings['state'], 'revision': settings['revision'], 'ignored': settings['ignored'], **({'reason': settings['reason']} if 'reason' in settings else {})}, 'checks': {'state': ctx['checks']['state']}, 'roles_source': {'state': tk['state'], 'fallbacks': tk['fallbacks'], 'chat_state': ctx['chat'].get('state'), **({'reason': tk['reason']} if 'reason' in tk else {})}, 'role_definitions': [{'role': r.role, 'label': r.label, 'hint': r.hint, 'exists': r.exists, 'runs': r.runs, 'linked_to': r.linked_to} for r in ROLES], 'providers': providers, 'profiles': list(settings['profiles'].values()), 'limits': {'description': MAX_DESCRIPTION, 'params_billion': MAX_PARAMS_BILLION, **{name: list(bounds) for name, bounds in LIMITS.items()}}, 'test_message': TEST_MESSAGE, 'live_check': {'authorized': bool(self.checker.authorized), 'reason': None if self.checker.authorized else self.checker.reason}, 'cards': [self._card(ctx, spec) for spec in ctx['registry'].list_model_specs()], 'view': self.view()}

class _FixtureTransport:

    def __init__(self, response):
        self.response = response

    async def send(self, payload, *, timeout_seconds):
        return deepcopy(self.response)

def execute(self, prepared):
    if self._refuse:
        return chat.ChatResult(chat.Outcome.REJECTED, chat.Execution.NOT_STARTED, prepared.model, prepared.request_ref, error_code='fixture_refused')
    return asyncio.run(chat.execute_request(prepared, transport=self._transport))
